#!/usr/bin/env bash
# Build, start the whole app, run the Playwright specs present in e2e/specs, then stop.
set -euo pipefail
cd "$(dirname "$0")/.."

export PORT="${PORT:-3000}"
export BASE_URL="http://localhost:${PORT}"
# Known audit file, shared by the app (bin/start) and the specs (support/audit.ts). Absolute.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

# Refuse to run against a server that is not ours: an app left running on $PORT (an earlier
# bin/start that was never stopped, another sandbox) would take the tests and fail them all.
if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then
  echo "bin/e2e: something is already serving on port ${PORT}; stop it (bin/stop) or set PORT to a free port" >&2
  exit 2
fi

bin/build
bin/start
cleanup() { bin/stop || true; }
trap cleanup EXIT

# Wait for readiness (Actuator health), then run the Playwright specs against BASE_URL. A loaded
# machine can take minutes to bring the JVM up; running the specs before it is ready fails every
# one of them for no reason, so wait long and fail loudly rather than run against nothing.
ready=0
for i in $(seq 1 300); do
  if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then ready=1; break; fi
  sleep 1
done
if [ "$ready" != 1 ]; then
  echo "bin/e2e: the app did not become healthy on port ${PORT} within 300s; see .run/app.log" >&2
  exit 2
fi

# Install deps + the Chromium browser (both cached after first run), then run the specs.
( cd e2e && npm ci --silent && npx --yes playwright install chromium && npx playwright test )
  protected othersOf(personId: number): PersonView[] {
    return this.othersByPerson().get(personId) ?? [];
  }

  /** Quick-add a DRAFT claim for the named person, adding them first (grade A) when not on the sheet. */
  protected quickAdd(): void {
    // A second submit before the first has answered is ignored, so it stores one record.
    if (this.quickSaving()) return;
    this.quickError.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const value = this.quickForm.getRawValue();
    if (value.name.trim() === '') {
      this.quickError.set('Type a name for the person.');
      return;
    }
    const amount = value.amount.trim();
    if (!AMOUNT_PATTERN.test(amount)) {
      this.quickError.set('Type an amount of 0.00 or more, with up to two decimals.');
      return;
    }
    this.quickSaving.set(true);
    this.claimsApi.quickAdd(sheet.id, value.name, amount).subscribe({
      next: ({ person, personAdded, claim }) => {
        this.quickSaving.set(false);
        if (personAdded) this.people.update((list) => [...list, person]);
        this.claimSaved(claim);
        this.quickForm.reset({ name: '', amount: '' }, { emitEvent: false });
      },
      error: (err: unknown) => {
        this.quickSaving.set(false);
        this.quickError.set(
          err instanceof HttpErrorResponse && err.status === 423
            ? 'That claim is due by inside a closed period.'
            : err instanceof HttpErrorResponse && err.status === 422
              ? 'That claim is dated after the person retired.'
            : err instanceof HttpErrorResponse && err.status === 409
              ? 'That name is already in use on this sheet.'
              : 'Could not add that claim.',
        );
      },

